from typing import List

def parse_music(music_string: str) -> List[int]:
    beat_map = {'o': 4, 'o|': 2, '.|': 1}
    beats = []

    # Split the music string by space to process each note separately
    notes = music_string.split(' ')

    for note in notes:
        # Check if the note is a whole note, half note, or quarter note
        if note.endswith('o'):
            beats.append(beat_map[note])
        elif note.endswith('|'):
            # Half note lasts two beats
            beats.append(beat_map[note] * 2)
        elif note.endswith('|.'):
            # Quarter note lasts one beat
            beats.append(beat_map[note])

    return beats
