import math


def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True


def is_multiply_prime(a):
    """Check if a number is the product of exactly three prime numbers."""
    if a <= 0 or a >= 100:
        return False  # a must be a positive integer less than 100
    primes_count = 0
    for i in range(2, a):
        if is_prime(i) and a % i == 0:
            primes_count += 1
            if primes_count > 3:
                return False
    return primes_count == 3

```

